  `SongId` NUMBER,
  `Title` TEXT,
  PRIMARY KEY (`SongId`)
);

CREATE TABLE `Albums` (
  `AId` NUMBER,
  `Title` TEXT,
  `Year` NUMBER,
  `Label` TEXT,
  `Type` TEXT,
  PRIMARY KEY (`AId`)
);

CREATE TABLE `Band` (
  `Id` NUMBER,
  `Firstname` TEXT,
  `Lastname` TEXT,
  PRIMARY KEY (`Id`)
);

CREATE TABLE `Instruments` (
  `SongId` NUMBER REFERENCES `Songs`(`SongId`),
  `BandmateId` NUMBER REFERENCES `Band`(`Id`),
  `Instrument` TEXT,
  PRIMARY KEY (`SongId`)
);

CREATE TABLE `Performance` (
  `SongId` NUMBER REFERENCES `Songs`(`SongId`),
  `Bandmate` NUMBER REFERENCES `Band`(`Id`),
  `StagePosition` TEXT,
  PRIMARY KEY (`SongId`)
);

CREATE TABLE `Tracklists` (
  `AlbumId` NUMBER REFERENCES `Albums`(`AId`),
  `Position` NUMBER,
  `SongId` NUMBER REFERENCES `Songs`(`SongId`),
  PRIMARY KEY (`AlbumId`)
);

CREATE TABLE `Vocals` (
  `SongId` NUMBER REFERENCES `Songs`(`SongId`),
  `Bandmate` NUMBER REFERENCES `Band`(`Id`),
  `Type` TEXT,
  PRIMARY KEY (`SongId`)
);

